-- ============================================================================
-- Query Lab dataset: hr
-- Northwind Labs, a 200-person tech company: org chart, salaries, history, projects, hiring.
--
-- Generated by tools/gen_query_lab_data.py (deterministic; do not edit by hand).
-- Load into the lab Postgres:   psql "postgresql://dsa:dsa@localhost:5544/dsa" -f SQL/lab/datasets/hr.sql
-- Then:                         SET search_path TO hr;
-- Tables: departments, employees, salary_history, projects, employee_projects, job_applications
-- ============================================================================
DROP SCHEMA IF EXISTS hr CASCADE;
CREATE SCHEMA hr;
SET search_path TO hr;


CREATE TABLE departments (
    dept_id   INT PRIMARY KEY,
    name      TEXT NOT NULL UNIQUE,
    city      TEXT NOT NULL,
    country   TEXT NOT NULL,
    budget    NUMERIC(12,2) NOT NULL
);
CREATE TABLE employees (
    emp_id           INT PRIMARY KEY,
    first_name       TEXT NOT NULL,
    last_name        TEXT NOT NULL,
    email            TEXT NOT NULL UNIQUE,
    job_title        TEXT NOT NULL,
    level            TEXT NOT NULL,
    dept_id          INT NOT NULL REFERENCES departments(dept_id),
    manager_id       INT REFERENCES employees(emp_id),
    salary           NUMERIC(10,2) NOT NULL,
    commission_pct   NUMERIC(4,2),
    hire_date        DATE NOT NULL,
    termination_date DATE,
    birth_date       DATE NOT NULL,
    gender           CHAR(1) NOT NULL,
    city             TEXT NOT NULL,
    country          TEXT NOT NULL
);
CREATE TABLE salary_history (
    emp_id         INT NOT NULL REFERENCES employees(emp_id),
    salary         NUMERIC(10,2) NOT NULL,
    effective_from DATE NOT NULL,
    effective_to   DATE,
    reason         TEXT NOT NULL,
    PRIMARY KEY (emp_id, effective_from)
);
CREATE TABLE projects (
    project_id INT PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    dept_id    INT NOT NULL REFERENCES departments(dept_id),
    start_date DATE NOT NULL,
    end_date   DATE,
    status     TEXT NOT NULL,
    budget     NUMERIC(12,2) NOT NULL
);
CREATE TABLE employee_projects (
    emp_id         INT NOT NULL REFERENCES employees(emp_id),
    project_id     INT NOT NULL REFERENCES projects(project_id),
    role           TEXT NOT NULL,
    hours_per_week INT NOT NULL,
    PRIMARY KEY (emp_id, project_id)
);
CREATE TABLE job_applications (
    application_id INT PRIMARY KEY,
    applicant_name TEXT NOT NULL,
    email          TEXT NOT NULL,
    position       TEXT NOT NULL,
    applied_at     TIMESTAMPTZ NOT NULL,
    source         TEXT NOT NULL,
    stage          TEXT NOT NULL
);


CREATE INDEX ON employees (dept_id);
CREATE INDEX ON employees (manager_id);
ANALYZE;
